class IntegrationJobExecutionTest {
 static class MutableClock extends Clock{Instant value=Instant.now();public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId ignored){return this;}public Instant instant(){return value;}void advance(long seconds){value=value.plusSeconds(seconds);}}
 private JdbcTemplate jdbc,admin;private TransactionTemplate tx;private JobRepository jobs;private JobExecution execution;private PlatformStore store;private AuditWriter audit;private MutableClock clock;private final List<UUID> ids=new ArrayList<>();
 @BeforeEach void setup(){
  String url=System.getenv("NIGSON_TEST_JDBC_URL");Assumptions.assumeTrue(url!=null,"native isolated integration database required");if(!url.matches("jdbc:postgresql://127.0.0.1:[0-9]+/nigson"))throw new IllegalArgumentException("LOCAL_INTEGRATION_DB_REQUIRED");var ds=new DriverManagerDataSource(url+"?currentSchema=integration","nigson_integration_app","mock-integration-runtime");jdbc=new JdbcTemplate(ds);admin=new JdbcTemplate(new DriverManagerDataSource(url,"nigson_bootstrap","mock-bootstrap"));var manager=new DataSourceTransactionManager(ds);tx=new TransactionTemplate(manager);clock=new MutableClock();var metrics=new SimpleMeterRegistry();jobs=new JdbcJobRepository(jdbc,clock);audit=new AuditWriter(jdbc,clock,metrics);execution=new JobExecution(jdbc,manager,jobs,audit,clock,metrics);store=new PlatformStore(jdbc,manager,clock,metrics);
 }
 @AfterEach void cleanup(){if(jdbc!=null){for(UUID id:ids)jdbc.update("DELETE FROM integration.integration_job WHERE id=?",id);jdbc.update("DELETE FROM integration.provider_cursor WHERE provider='COMMERCE_PAYMENT' AND job_kind='PAYMENT_RECONCILE'");}ids.clear();}
 private JobRepository.Record enqueue(){var job=tx.execute(s->jobs.enqueue(JobValues.Kind.PAYMENT_RECONCILE,"execution:"+UUID.randomUUID(),"commerce",UUID.randomUUID()));ids.add(job.id());return job;}
 private JobExecution.Claim claim(){return execution.claim(Set.of(JobValues.Kind.PAYMENT_RECONCILE),1,Duration.ofSeconds(30)).getFirst();}
 @Test void concurrentWorkersClaimOneExecutionAndWrongProviderCannotAdvanceCursor()throws Exception{
  var job=enqueue();try(var pool=Executors.newFixedThreadPool(2)){var start=new CountDownLatch(1);var tasks=new ArrayList<Future<List<JobExecution.Claim>>>();for(int i=0;i<2;i++)tasks.add(pool.submit(()->{start.await();return execution.claim(Set.of(JobValues.Kind.PAYMENT_RECONCILE),1,Duration.ofSeconds(30));}));start.countDown();var claims=new ArrayList<JobExecution.Claim>();for(var result:tasks)claims.addAll(result.get(10,TimeUnit.SECONDS));assertThat(claims).hasSize(1);assertThat(jobs.find(job.id(),false).attempts()).isEqualTo(1);assertThatThrownBy(()->execution.finish(claims.getFirst(),JobHandler.Provider.FEDEX,new JobHandler.Outcome(JobValues.State.SUCCEEDED,null,null),UUID.randomUUID())).isInstanceOfSatisfying(Problem.Failure.class,f->assertThat(f.code).isEqualTo(ProblemCode.PROVIDER_MODE_MISMATCH));assertThat(jdbc.queryForObject("SELECT count(*) FROM integration.provider_cursor",Integer.class)).isZero();}
 }
 @Test void expiredExecutionBecomesUnknownAndOldGenerationCannotCommit(){
  var job=enqueue();var first=claim();assertThat(first.uncertain()).isFalse();assertThat(first.commandKey()).hasSize(100);clock.advance(31);var recovered=claim();assertThat(recovered.uncertain()).isTrue();assertThat(recovered.commandKey()).isEqualTo(first.commandKey());assertThat(recovered.job().businessKey()).isEqualTo(job.businessKey());assertThat(recovered.job().attempts()).isEqualTo(2);assertThat(execution.finish(first,JobHandler.Provider.COMMERCE_PAYMENT,new JobHandler.Outcome(JobValues.State.SUCCEEDED,null,null),UUID.randomUUID())).isFalse();assertThat(jdbc.queryForObject("SELECT count(*) FROM integration.provider_cursor",Integer.class)).isZero();
  assertThat(execution.finish(recovered,JobHandler.Provider.COMMERCE_PAYMENT,new JobHandler.Outcome(JobValues.State.SUCCEEDED,null,null),UUID.randomUUID())).isTrue();assertThat(jobs.find(job.id(),false).state()).isEqualTo(JobValues.State.SUCCEEDED);
 }
 @Test void checkpointAndOutcomeRollbackTogetherOnAuditFailure(){
  var job=enqueue();var claim=claim();admin.execute("REVOKE INSERT ON integration.audit_record FROM nigson_integration_app");try{assertThatThrownBy(()->execution.finish(claim,JobHandler.Provider.COMMERCE_PAYMENT,new JobHandler.Outcome(JobValues.State.SUCCEEDED,null,null),UUID.randomUUID())).isInstanceOf(org.springframework.dao.DataAccessException.class);}finally{admin.execute("GRANT INSERT ON integration.audit_record TO nigson_integration_app");}
  assertThat(jobs.find(job.id(),false).state()).isEqualTo(JobValues.State.CLAIMED);assertThat(jdbc.queryForObject("SELECT count(*) FROM integration.provider_cursor",Integer.class)).isZero();assertThat(execution.finish(claim,JobHandler.Provider.COMMERCE_PAYMENT,new JobHandler.Outcome(JobValues.State.SUCCEEDED,null,null),UUID.randomUUID())).isTrue();assertThat(execution.finish(claim,JobHandler.Provider.COMMERCE_PAYMENT,new JobHandler.Outcome(JobValues.State.SUCCEEDED,null,null),UUID.randomUUID())).isFalse();assertThat(jdbc.queryForObject("SELECT version FROM integration.provider_cursor WHERE provider='COMMERCE_PAYMENT'",Long.class)).isZero();
 }
 @Test void lostPrivateAcknowledgementReconcilesOriginalPageBeforeAdvancing()throws Exception{
  var job=enqueue();String cursor=Base64.getUrlEncoder().withoutPadding().encodeToString(("1:"+UUID.randomUUID()).getBytes(StandardCharsets.UTF_8));var requests=new CopyOnWriteArrayList<String>();var keys=new CopyOnWriteArrayList<String>();var calls=new AtomicInteger();var source=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);
  try(var pool=Executors.newVirtualThreadPerTaskExecutor()){
   source.setExecutor(pool);source.createContext("/internal/v1/payments/reconciliation",exchange->{String body=new String(exchange.getRequestBody().readAllBytes(),StandardCharsets.UTF_8);requests.add(body);keys.add(exchange.getRequestHeaders().getFirst("Idempotency-Key"));int count=calls.incrementAndGet();var input=EventCodec.JSON.readTree(body);var result=EventCodec.JSON.createObjectNode().put("processed",1).put("mismatches",0);if(input.has("cursor"))result.putNull("nextCursor");else result.put("nextCursor",cursor);byte[] bytes=EventCodec.JSON.writeValueAsBytes(result);
    // Durable remote command is accepted before its first response is lost to the request deadline.
    if(count==1)try{Thread.sleep(7000);}catch(InterruptedException interrupted){Thread.currentThread().interrupt();}try{exchange.getResponseHeaders().set("Content-Type","application/json");exchange.sendResponseHeaders(202,bytes.length);try(var out=exchange.getResponseBody()){out.write(bytes);}}catch(java.io.IOException cancelled){exchange.close();}
   });source.start();try{
    var handler=new PaymentReconciliationHandler("test","http://127.0.0.1:"+source.getAddress().getPort(),25,route->{assertThat(TransactionSynchronizationManager.isActualTransactionActive()).isFalse();assertThat(route.api()).isEqualTo("API-118");return "synthetic-local-workload";});var worker=new JobWorker(execution,List.of(handler),1);
    assertThat(worker.poll()).isEqualTo(1);assertThat(jobs.find(job.id(),false).state()).isEqualTo(JobValues.State.UNKNOWN);assertThat(jdbc.queryForObject("SELECT count(*) FROM integration.provider_cursor",Integer.class)).isZero();clock.advance(31);assertThat(worker.poll()).isEqualTo(1);assertThat(jobs.find(job.id(),false).state()).isEqualTo(JobValues.State.PENDING);assertThat(worker.poll()).isEqualTo(1);assertThat(jobs.find(job.id(),false).state()).isEqualTo(JobValues.State.SUCCEEDED);
    assertThat(keys).hasSize(3);assertThat(keys.get(0)).isEqualTo(keys.get(1));assertThat(keys.get(2)).isNotEqualTo(keys.get(1));assertThat(requests.get(0)).isEqualTo(requests.get(1));assertThat(EventCodec.JSON.readTree(requests.get(0)).has("cursor")).isFalse();assertThat(EventCodec.JSON.readTree(requests.get(2)).path("cursor").asString()).isEqualTo(cursor);assertThat(jdbc.queryForObject("SELECT checkpoint->>'completed' FROM integration.provider_cursor WHERE provider='COMMERCE_PAYMENT'",String.class)).isEqualTo("true");
   }finally{source.stop(0);}
  }
 }
 @Test void actualSnsSqsDeliveryCommitsOwnedIntentBeforeAcknowledgement()throws Exception{
  String endpoint=System.getenv("NIGSON_TEST_EVENT_ENDPOINT");Assumptions.assumeTrue(endpoint!=null,"isolated LocalStack required");if(!endpoint.matches("http://127.0.0.1:[0-9]+"))throw new IllegalArgumentException("LOCAL_EVENT_ENDPOINT_REQUIRED");var credentials=software.amazon.awssdk.auth.credentials.StaticCredentialsProvider.create(software.amazon.awssdk.auth.credentials.AwsBasicCredentials.create("mock-localstack","mock-localstack"));
  try(var sns=software.amazon.awssdk.services.sns.SnsClient.builder().endpointOverride(URI.create(endpoint)).credentialsProvider(credentials).region(software.amazon.awssdk.regions.Region.US_EAST_1).build();var sqs=software.amazon.awssdk.services.sqs.SqsClient.builder().endpointOverride(URI.create(endpoint)).credentialsProvider(credentials).region(software.amazon.awssdk.regions.Region.US_EAST_1).build()){
   String suffix=UUID.randomUUID().toString(),topic=sns.createTopic(r->r.name("integration-order-"+suffix)).topicArn(),queue=sqs.createQueue(r->r.queueName("integration-order-"+suffix)).queueUrl(),dead=sqs.createQueue(r->r.queueName("integration-order-dead-"+suffix)).queueUrl();String arn=sqs.getQueueAttributes(r->r.queueUrl(queue).attributeNamesWithStrings("QueueArn")).attributesAsStrings().get("QueueArn");sns.subscribe(r->r.topicArn(topic).protocol("sqs").endpoint(arn).attributes(Map.of("RawMessageDelivery","true","FilterPolicyScope","MessageBody","FilterPolicy","{\"producer\":[\"commerce\"],\"event_type\":[\"order.pending.v1\"]}")));
   var event=(tools.jackson.databind.node.ObjectNode)EventCodec.JSON.readTree(java.nio.file.Files.readString(java.nio.file.Path.of(System.getenv("NIGSON_EVENT_FIXTURES"),"order.pending.v1.json")));UUID order=UUID.randomUUID();event.put("event_id",UUID.randomUUID().toString()).put("aggregate_id",order.toString());((tools.jackson.databind.node.ObjectNode)event.get("payload")).put("order_id",order.toString()).put("market_code","NG");String body=EventCodec.JSON.writeValueAsString(event);var handler=new OrderPendingHandler(jobs,audit);var handlers=Map.<String,java.util.function.BiFunction<JdbcTemplate,tools.jackson.databind.JsonNode,String>>of(handler.eventType(),handler::handle);
   try(var pump=new EventPump(store,sns,sqs,topic,queue,dead,1,handlers)){try{
    sns.publish(r->r.topicArn(topic).message(body));List<software.amazon.awssdk.services.sqs.model.Message> received=List.of();for(int i=0;i<5&&received.isEmpty();i++)received=sqs.receiveMessage(r->r.queueUrl(queue).waitTimeSeconds(1).maxNumberOfMessages(1)).messages();assertThat(received).hasSize(1);admin.execute("REVOKE INSERT ON integration.audit_record FROM nigson_integration_app");try{assertThat(pump.process(received.getFirst())).isFalse();assertThat(jdbc.queryForObject("SELECT count(*) FROM integration.integration_job WHERE business_key=?",Integer.class,"payment-reconcile:"+order)).isZero();assertThat(jdbc.queryForObject("SELECT count(*) FROM integration.processed_event WHERE event_id=?",Integer.class,UUID.fromString(event.path("event_id").asString()))).isZero();}finally{admin.execute("GRANT INSERT ON integration.audit_record TO nigson_integration_app");}assertThat(pump.process(received.getFirst())).isTrue();UUID id=jdbc.queryForObject("SELECT id FROM integration.integration_job WHERE business_key=?",UUID.class,"payment-reconcile:"+order);ids.add(id);assertThat(jdbc.queryForObject("SELECT count(*) FROM integration.processed_event WHERE event_id=?",Integer.class,UUID.fromString(event.path("event_id").asString()))).isEqualTo(1);assertThat(sqs.receiveMessage(r->r.queueUrl(queue).waitTimeSeconds(1)).messages()).isEmpty();
    sqs.sendMessage(r->r.queueUrl(queue).messageBody(body));var duplicate=sqs.receiveMessage(r->r.queueUrl(queue).waitTimeSeconds(1)).messages();assertThat(duplicate).hasSize(1);assertThat(pump.process(duplicate.getFirst())).isTrue();assertThat(jdbc.queryForObject("SELECT count(*) FROM integration.integration_job WHERE business_key=?",Integer.class,"payment-reconcile:"+order)).isEqualTo(1);
   }finally{sqs.deleteQueue(r->r.queueUrl(queue));sqs.deleteQueue(r->r.queueUrl(dead));sns.deleteTopic(r->r.topicArn(topic));}}
  }
 }
 @Test void eventInboxAndStableIntentCommitOnceForSemanticDuplicates()throws Exception{
  var value=(tools.jackson.databind.node.ObjectNode)EventCodec.JSON.readTree(java.nio.file.Files.readString(java.nio.file.Path.of(System.getenv("NIGSON_EVENT_FIXTURES"),"order.pending.v1.json")));UUID order=UUID.randomUUID();value.put("event_id",UUID.randomUUID().toString()).put("aggregate_id",order.toString());var payload=(tools.jackson.databind.node.ObjectNode)value.get("payload");payload.put("order_id",order.toString()).put("market_code","NG");var handler=new OrderPendingHandler(jobs,audit);String consumer="synthetic-order-pending";assertThat(handler.eventType()).isEqualTo("order.pending.v1");String body=EventCodec.JSON.writeValueAsString(value);assertThat(store.consume(consumer,body,1,handler::handle)).isTrue();var saved=jdbc.queryForObject("SELECT id FROM integration.integration_job WHERE business_key=?",UUID.class,"payment-reconcile:"+order);ids.add(saved);assertThat(store.consume(consumer,body,1,handler::handle)).isFalse();value.put("event_id",UUID.randomUUID().toString());assertThat(store.consume(consumer,EventCodec.JSON.writeValueAsString(value),1,handler::handle)).isTrue();assertThat(jdbc.queryForObject("SELECT count(*) FROM integration.integration_job WHERE business_key=?",Integer.class,"payment-reconcile:"+order)).isEqualTo(1);assertThat(jdbc.queryForObject("SELECT count(*) FROM integration.audit_record WHERE resource_id=?",Integer.class,saved)).isEqualTo(1);
 }
}
